package main

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"sort"
	"strings"

	"github.com/bernard0331/personal-site/services/genshin-calc/catalog"
)

// display.json holds English names and icon filenames for catalog keys
// (generated by tools/gen_display.py from the genshin-db API).
//
//go:embed display.json
var displayJSON []byte

type display struct {
	Characters map[string]struct {
		Name string `json:"name"`
		Icon string `json:"icon"`
	} `json:"characters"`
	Weapons map[string]struct {
		Name string `json:"name"`
		Icon string `json:"icon"`
	} `json:"weapons"`
	Sets map[string]struct {
		Name    string `json:"name"`
		Flower  string `json:"flower"`
		Plume   string `json:"plume"`
		Sands   string `json:"sands"`
		Goblet  string `json:"goblet"`
		Circlet string `json:"circlet"`
	} `json:"artifact_sets"`
}

// catalogResponse is what /api/catalog returns. It is built once at start-up:
// the data only changes with a new simulator release.
type catalogResponse struct {
	Characters []apiCharacter `json:"characters"`
	Weapons    []apiWeapon    `json:"weapons"`
	Sets       []apiSet       `json:"sets"`
	body       []byte
	etag       string
}

type apiCharacter struct {
	Key        string `json:"key"`
	Name       string `json:"name"`
	Icon       string `json:"icon,omitempty"` // empty when no icon is known yet
	Element    string `json:"element"`
	WeaponType string `json:"weapon_type"`
	Rarity     int    `json:"rarity"`
	Caveat     string `json:"caveat,omitempty"` // shown on every team with this character
}

// caveats are warnings about characters whose results are less trustworthy
// than the rest. The page writes "<Name> is <caveat>" ("<A> and <B> are ..."
// when a team has several with the same caveat).
const newCharacter = "new: the simulator's model is recent, and its numbers may not match theorycrafters' calculations. Treat this team's DPS as rough."

var caveats = map[string]string{
	"mitya":   newCharacter,
	"valeriy": newCharacter,
}

type apiWeapon struct {
	Key        string `json:"key"`
	Name       string `json:"name"`
	Icon       string `json:"icon,omitempty"`
	WeaponType string `json:"weapon_type"`
	Rarity     int    `json:"rarity"`
	Craftable  bool   `json:"craftable,omitempty"` // forged at a blacksmith: unlimited R5 copies
}

type apiSet struct {
	Key   string            `json:"key"`
	Name  string            `json:"name"`
	Icons map[string]string `json:"icons"` // slot -> icon
}

func buildCatalog() (*catalogResponse, error) {
	cat, err := catalog.Load()
	if err != nil {
		return nil, err
	}
	var d display
	if err := json.Unmarshal(displayJSON, &d); err != nil {
		return nil, err
	}
	out := &catalogResponse{}
	for _, c := range cat.Characters {
		// Unreleased characters are never calculated, so never offered. Every
		// player is assumed to be Lumine, so Aether's entries are left out.
		if !c.Released || len(c.Key) > 6 && c.Key[:6] == "aether" {
			continue
		}
		dc := d.Characters[c.Key]
		name := dc.Name
		if name == "" {
			// Too new for the display data: the key, capitalised, beats nothing.
			name = strings.ToUpper(c.Key[:1]) + c.Key[1:]
		}
		out.Characters = append(out.Characters, apiCharacter{c.Key, name, dc.Icon, c.Element, c.WeaponType, c.Rarity, caveats[c.Key]})
	}
	for _, w := range cat.Weapons {
		dw := d.Weapons[w.Key]
		name := dw.Name
		if name == "" {
			name = w.Key
		}
		out.Weapons = append(out.Weapons, apiWeapon{w.Key, name, dw.Icon, w.WeaponType, w.Rarity, w.Craftable})
	}
	for key, s := range d.Sets {
		if !cat.HasArtifactSet(key) {
			continue
		}
		out.Sets = append(out.Sets, apiSet{key, s.Name, map[string]string{
			"flower": s.Flower, "plume": s.Plume, "sands": s.Sands, "goblet": s.Goblet, "circlet": s.Circlet}})
	}
	sort.Slice(out.Characters, func(i, j int) bool { return out.Characters[i].Name < out.Characters[j].Name })
	sort.Slice(out.Weapons, func(i, j int) bool { return out.Weapons[i].Name < out.Weapons[j].Name })
	sort.Slice(out.Sets, func(i, j int) bool { return out.Sets[i].Name < out.Sets[j].Name })
	out.body, err = json.Marshal(out)
	sum := sha256.Sum256(out.body)
	out.etag = `"` + hex.EncodeToString(sum[:8]) + `"`
	return out, err
}

// serve sends the catalog with an ETag (a fingerprint of its contents) and
// asks browsers to check it every time: an unchanged catalog costs a tiny
// "304 Not Modified", and a new release is picked up at once.
func (c *catalogResponse) serve(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("ETag", c.etag)
	if r.Header.Get("If-None-Match") == c.etag {
		w.WriteHeader(http.StatusNotModified)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(c.body)
}
